package com.arthurchenevans.arsbotania.client;

import com.arthurchenevans.arsbotania.core.divine.ArcanistClass;
import com.arthurchenevans.arsbotania.item.DivineArmorItem;
import com.hollingsworth.arsnouveau.client.renderer.item.ArmorRenderer;
import com.hollingsworth.arsnouveau.common.armor.AnimatedMagicArmor;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.model.GeoModel;

/**
 * Ars's armor renderer, pointed at the Divine texture: pearl cloth with an animated rainbow
 * trim (generated by tools/divine_recolor.py). Divine ignores dye colour; it has one look.
 */
public class DivineArmorRenderer extends ArmorRenderer {
    private final ResourceLocation texture;

    public DivineArmorRenderer(GeoModel<AnimatedMagicArmor> model, ArcanistClass cls) {
        super(model);
        this.texture = DivineArmorItem.textureFor(cls);
    }

    @Override
    public ResourceLocation getTextureLocation(AnimatedMagicArmor instance) {
        return texture;
    }
}
